<script setup lang="ts">import{computed,onBeforeUnmount,onMounted,ref}from'vue';import{useRouter}from'vue-router';import{studentAPI}from'../../api/student';import type{Model,ModelCategory,ModelStatus}from'../../api/types';import StatusBadge from'../../components/StatusBadge.vue';import EmptyState from'../../components/EmptyState.vue';import{APIError}from'../../api/client';const rows=ref<Model[]>([]),query=ref(''),category=ref<ModelCategory|''>(''),status=ref<ModelStatus|''>(''),expanded=ref(''),error=ref(''),router=useRouter();const filtered=computed(()=>rows.value.filter(m=>(!query.value||`${m.display_name} ${m.model_id} ${m.capabilities.join(' ')}`.toLowerCase().includes(query.value.toLowerCase()))&&(!category.value||m.category===category.value)&&(!status.value||m.status===status.value)));async function load(){try{rows.value=await studentAPI.models()}catch(e){error.value=e instanceof APIError?e.message:'加载模型失败'}}function refresh(){void load()};onMounted(()=>{void load();window.addEventListener('nebula:refresh',refresh)});onBeforeUnmount(()=>window.removeEventListener('nebula:refresh',refresh));</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">STUDENT</p><h1>模型广场</h1><p class="muted">平台 ACTIVE 常用模型，以及你已获批或生效 Key 中的模型。</p></div><button class="button primary" @click="router.push('/student/api-keys?step=models')">申请新模型</button></div><p v-if="error" class="error banner">{{error}}</p><section class="panel"><div class="grid two"><label>搜索<input v-model="query" placeholder="名称、模型 ID 或能力"/></label><div class="row"><label>类别<select v-model="category"><option value="">全部类别</option><option v-for="v in ['text','image','audio','video','multimodal','embedding','rerank']" :key="v">{{v}}</option></select></label><label>状态<select v-model="status"><option value="">全部状态</option><option value="active">已启用</option><option value="inactive">已停用</option><option value="pending_configuration">待配置</option></select></label></div></div></section><div v-if="filtered.length" class="grid two" style="margin-top:20px"><article v-for="model in filtered" :key="model.id" class="panel"><div class="row"><div><strong>{{model.display_name}}</strong><p class="muted">{{model.model_id}} · {{model.category}}</p></div><StatusBadge :status="model.status"/></div><p class="muted">{{model.description||'暂无模型说明'}}</p><button class="button ghost" @click="expanded=expanded===model.id?'':model.id">{{expanded===model.id?'收起':'查看详情'}}</button><dl v-if="expanded===model.id"><dt>能力</dt><dd>{{model.capabilities.join('、')||'—'}}</dd><dt>输入 / 输出</dt><dd>{{model.input_modalities.join('、')}} / {{model.output_modalities.join('、')}}</dd><dt>上下文 / 最大输出</dt><dd>{{model.context_window??'未提供'}} / {{model.max_output_tokens??'未提供'}}</dd></dl></article></div><EmptyState v-else title="没有匹配的模型" description="调整搜索或筛选条件。"/></section></template>
